import React, { useState, useEffect } from "react";

const portrait =
  "data:image/jpeg;base64,"; // EDIT ME: replace with your own base64 image or import

const LEVEL_COLORS_LIGHT = [
  "#ebedf0",
  "#9be9a8",
  "#40c463",
  "#30a14e",
  "#216e39",
];
const LEVEL_COLORS_DARK = [
  "#161b22",
  "#0e4429",
  "#006d32",
  "#26a641",
  "#39d353",
];
const CUBE_LEVEL_HEIGHT = [3, 10, 16, 22, 30]; // extrusion height per contribution level
const TILE_W = 22; // isometric tile width (top diamond)
const TILE_H = 12; // isometric tile height (top diamond)

function shadeColor(hex, factor) {
  const num = parseInt(hex.replace("#", ""), 16);
  const r = Math.round(((num >> 16) & 255) * factor);
  const g = Math.round(((num >> 8) & 255) * factor);
  const b = Math.round((num & 255) * factor);
  return `rgb(${r},${g},${b})`;
}

function levelFromCount(count) {
  if (count === 0) return 0;
  if (count <= 2) return 1;
  if (count <= 5) return 2;
  if (count <= 9) return 3;
  return 4;
}

function GitHubCalendar({ username, dark }) {
  const [weeks, setWeeks] = useState(null); // array of weeks, each an array of 7 day-cells (or null for padding)
  const [status, setStatus] = useState("loading"); // loading | ready | error
  const [tooltip, setTooltip] = useState(null);

  const LEVEL_COLORS = dark ? LEVEL_COLORS_DARK : LEVEL_COLORS_LIGHT;
  const borderColor = dark ? "rgba(255,255,255,0.12)" : "rgba(0,0,0,0.08)";
  const textColor = dark ? "#f2f2f2" : "#111111";
  const subTextColor = dark ? "rgba(242,242,242,0.5)" : "rgba(0,0,0,0.45)";

  // Fetch contribution data as early as possible
  useEffect(() => {
    let cancelled = false;

    fetch(`https://github-contributions-api.jogruber.de/v4/${username}?y=last`)
      .then((res) => {
        if (!res.ok) throw new Error("bad response");
        return res.json();
      })
      .then((data) => {
        if (cancelled) return;
        const days = (data.contributions || []).map((d) => ({
          date: d.date,
          count: d.count,
          level:
            typeof d.level === "number" ? d.level : levelFromCount(d.count),
        }));
        if (days.length === 0) throw new Error("empty");

        const firstDate = new Date(days[0].date + "T00:00:00");
        const leadingBlanks = firstDate.getDay(); // 0 = Sunday
        const padded = Array(leadingBlanks).fill(null).concat(days);

        const weekCols = [];
        for (let i = 0; i < padded.length; i += 7) {
          weekCols.push(padded.slice(i, i + 7));
        }
        setWeeks(weekCols);
        setStatus("ready");
      })
      .catch(() => {
        if (!cancelled) setStatus("error");
      });

    return () => {
      cancelled = true;
    };
  }, [username]);

  function formatDateLabel(dateStr) {
    const d = new Date(dateStr + "T00:00:00");
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
  }

  if (status === "error") {
    // Fallback to the static (non-interactive) image if the live API is unreachable
    return (
      <div
        style={{
          border: `1px solid ${borderColor}`,
          borderRadius: 16,
          padding: "20px 16px",
        }}
      >
        <img
          src={`https://ghchart.rshah.org/${username}`}
          alt={`${username}'s GitHub contribution graph`}
          style={{ width: "100%", display: "block" }}
        />
      </div>
    );
  }

  // Isometric grid: trim dead leading weeks so the chart reads as full/dense
  // rather than mostly empty tiles, and cap how far back it goes.
  const FALLBACK_WEEKS = 12;
  const MAX_WEEKS_SHOWN = 24;
  let recentWeeks;
  if (weeks) {
    const firstActiveWeek = weeks.findIndex((week) =>
      week.some((d) => d && d.level > 0),
    );
    const start =
      firstActiveWeek === -1
        ? Math.max(0, weeks.length - FALLBACK_WEEKS)
        : Math.max(0, firstActiveWeek - 1);
    recentWeeks = weeks
      .slice(start)
      .slice(-MAX_WEEKS_SHOWN);
  } else {
    recentWeeks = Array.from({ length: FALLBACK_WEEKS }, () => Array(7).fill(null));
  }
  const cols = recentWeeks.length;
  const rows = 7;

  const cubes = [];
  for (let col = 0; col < cols; col++) {
    for (let row = 0; row < rows; row++) {
      const day = recentWeeks[col][row];
      const level = status === "loading" ? 0 : day ? day.level : 0;
      const height =
        status === "loading" ? CUBE_LEVEL_HEIGHT[0] : CUBE_LEVEL_HEIGHT[level];
      const baseX = (col - row) * (TILE_W / 2);
      const baseY = (col + row) * (TILE_H / 2);
      cubes.push({ col, row, day, level, height, baseX, baseY });
    }
  }
  cubes.sort((a, b) => a.col + a.row - (b.col + b.row));

  let minX = Infinity,
    maxX = -Infinity,
    minY = Infinity,
    maxY = -Infinity;
  cubes.forEach(({ baseX, baseY, height }) => {
    minX = Math.min(minX, baseX - TILE_W / 2);
    maxX = Math.max(maxX, baseX + TILE_W / 2);
    minY = Math.min(minY, baseY - height - TILE_H / 2);
    maxY = Math.max(maxY, baseY + TILE_H / 2);
  });
  const svgWidth = maxX - minX;
  const svgHeight = maxY - minY;
  const offsetX = -minX;
  const offsetY = -minY;
  const toPath = (pts) => pts.map((p) => p.join(",")).join(" ");

  return (
    <div
      style={{
        border: `1px solid ${borderColor}`,
        borderRadius: 16,
        padding: "20px 16px",
      }}
    >
      {/* Header */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 16,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div
            style={{
              width: 28,
              height: 28,
              borderRadius: 8,
              background: dark ? "#2f3136" : "#1c2531",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none">
              <path
                d="M3 17l6-6 4 4 8-8"
                stroke="#7ee7a8"
                strokeWidth="2.4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d="M15 7h6v6"
                stroke="#7ee7a8"
                strokeWidth="2.4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </div>
          <span style={{ fontWeight: 600, fontSize: 15, color: textColor }}>
            Contributes
          </span>
        </div>
        <div style={{ display: "flex", gap: 3, padding: 4 }}>
          {[0, 1, 2].map((i) => (
            <span
              key={i}
              style={{
                width: 4,
                height: 4,
                borderRadius: "50%",
                background: subTextColor,
              }}
            />
          ))}
        </div>
      </div>

      {/* Isometric grid */}
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          overflowX: "auto",
          paddingBottom: 4,
        }}
      >
        <svg
          width={svgWidth}
          height={svgHeight}
          style={{ overflow: "visible", flexShrink: 0 }}
        >
          {cubes.map(({ col, row, day, level, height, baseX, baseY }) => {
            const x = baseX + offsetX;
            const y = baseY + offsetY;
            const topColor = LEVEL_COLORS[level];
            const leftColor = shadeColor(topColor, 0.62);
            const rightColor = shadeColor(topColor, 0.8);
            const isHovered = day && tooltip && tooltip.date === day.date;

            const topPts = [
              [x, y - height - TILE_H / 2],
              [x + TILE_W / 2, y - height],
              [x, y - height + TILE_H / 2],
              [x - TILE_W / 2, y - height],
            ];
            const leftPts = [
              [x - TILE_W / 2, y - height],
              [x, y - height + TILE_H / 2],
              [x, y + TILE_H / 2],
              [x - TILE_W / 2, y],
            ];
            const rightPts = [
              [x, y - height + TILE_H / 2],
              [x + TILE_W / 2, y - height],
              [x + TILE_W / 2, y],
              [x, y + TILE_H / 2],
            ];

            return (
              <g
                key={`${col}-${row}`}
                onMouseEnter={() =>
                  day && setTooltip({ date: day.date, count: day.count })
                }
                onMouseLeave={() => setTooltip(null)}
                style={{ cursor: day ? "pointer" : "default" }}
              >
                {height > 4 && (
                  <polygon points={toPath(leftPts)} fill={leftColor} />
                )}
                {height > 4 && (
                  <polygon points={toPath(rightPts)} fill={rightColor} />
                )}
                <polygon
                  points={toPath(topPts)}
                  fill={topColor}
                  stroke={isHovered ? (dark ? "#fff" : "#000") : "none"}
                  strokeOpacity={0.4}
                  strokeWidth={isHovered ? 1 : 0}
                />
              </g>
            );
          })}
        </svg>
      </div>

      {/* Hover detail */}
      <div
        style={{
          textAlign: "center",
          fontSize: 12,
          color: subTextColor,
          marginTop: 8,
          minHeight: 16,
        }}
      >
        {tooltip
          ? tooltip.count === 0
            ? `No contributions on ${formatDateLabel(tooltip.date)}`
            : `${tooltip.count} contribution${
                tooltip.count === 1 ? "" : "s"
              } on ${formatDateLabel(tooltip.date)}`
          : "Hover a block to see the day's activity"}
      </div>
    </div>
  );
}

